import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"GLM Free API — Puente de un solo archivo","description":"Una API completa compatible con OpenAI y Anthropic para GLM en un solo archivo Go. Sin navegador, sin Chrome headless, con pool de cuentas.","frontmatter":{"title":"GLM Free API — Puente de un solo archivo","description":"Una API completa compatible con OpenAI y Anthropic para GLM en un solo archivo Go. Sin navegador, sin Chrome headless, con pool de cuentas."},"headers":[],"relativePath":"es/projects/glm-free-api/index.md","filePath":"es/projects/glm-free-api/index.md"}`),a={name:`es/projects/glm-free-api/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="glm-free-api-—-puente-de-un-solo-archivo" tabindex="-1">GLM Free API — Puente de un solo archivo <a class="header-anchor" href="#glm-free-api-—-puente-de-un-solo-archivo" aria-label="Permalink to “GLM Free API — Puente de un solo archivo”">​</a></h1><p><strong><a href="https://github.com/Godde3s/glm-free-api" target="_blank" rel="noreferrer">GLM Free API</a></strong> es mi repositorio con más estrellas, y la premisa es casi descortés de simple: un puente API completo hacia GLM en <strong>un solo archivo Go</strong>, con <strong>cero automatización de navegador</strong>. Sin Chrome headless devorando RAM, sin caprichos de puppeteer — solo HTTP bien hecho.</p><h2 id="el-problema-que-resuelve" tabindex="-1">El problema que resuelve <a class="header-anchor" href="#el-problema-que-resuelve" aria-label="Permalink to “El problema que resuelve”">​</a></h2><p>El chat web de GLM es gratis pero está encerrado en un navegador. Los puentes existentes envuelven ese navegador en automatización, lo que significa explosiones de memoria, captchas a cada rato y caídas bajo carga. Yo fui por el camino contrario: hice ingeniería inversa del flujo de sesión web y implementé el protocolo nativamente en Go. El resultado arranca en milisegundos y aguanta peticiones concurrentes sin un solo proceso de navegador.</p><h2 id="caracteristicas" tabindex="-1">Características <a class="header-anchor" href="#caracteristicas" aria-label="Permalink to “Características”">​</a></h2><ul><li><strong>Compatible con OpenAI</strong> vía <code>/v1/chat/completions</code> — drop-in para cualquier cliente existente.</li><li><strong>Compatible con Anthropic</strong> vía <code>/v1/messages</code> — para que las herramientas estilo Claude también funcionen.</li><li><strong>Pool de cuentas</strong> — rota varias sesiones, marca las muertas, quédate bajo los límites de tasa.</li><li><strong>Streaming</strong> — SSE real, no respuestas troceadas falsas.</li><li><strong>Un archivo</strong> — <code>go build</code>, ejecuta, listo. Puedes leer toda la implementación de una sentada.</li></ul><blockquote><p>Un solo archivo no es un alarde. Es una declaración: la infraestructura debería ser legible — puedes auditar cada línea en diez minutos.</p></blockquote><p>La misma arquitectura tuvo hermanos: <a href="/Usf/es/projects/ghost-brain/">GhostBrain</a> (Gemini), qwen-free-api y deepseek-free-api. Junto con <a href="/Usf/es/projects/omnirouter/">OmniRouter</a>, forman una infraestructura de IA completa en tier gratuito que cuesta exactamente cero en ejecutarse.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};